import{_ as a,c as i,a0 as e,o as r}from"./chunks/framework.Dz1iyyfL.js";const m=JSON.parse('{"title":"HTML 核心知识点","description":"","frontmatter":{},"headers":[],"relativePath":"前端基础/HTML/HTML基础.md","filePath":"前端基础/HTML/HTML基础.md"}'),t={name:"前端基础/HTML/HTML基础.md"};function o(h,l,d,n,s,u){return r(),i("div",null,l[0]||(l[0]=[e('<h1 id="html-核心知识点" tabindex="-1">HTML 核心知识点 <a class="header-anchor" href="#html-核心知识点" aria-label="Permalink to &quot;HTML 核心知识点&quot;">​</a></h1><h2 id="一、html基础概念" tabindex="-1">一、HTML基础概念 <a class="header-anchor" href="#一、html基础概念" aria-label="Permalink to &quot;一、HTML基础概念&quot;">​</a></h2><ul><li>超文本标记语言（HyperText Markup Language）</li><li>最新标准为HTML5（2014年W3C正式发布）</li></ul><h2 id="二、html5核心特性" tabindex="-1">二、HTML5核心特性 <a class="header-anchor" href="#二、html5核心特性" aria-label="Permalink to &quot;二、HTML5核心特性&quot;">​</a></h2><h3 id="_1-语义化标签" tabindex="-1">1. 语义化标签 <a class="header-anchor" href="#_1-语义化标签" aria-label="Permalink to &quot;1. 语义化标签&quot;">​</a></h3><ul><li>新增结构化元素：header/nav/article/section/aside/footer等</li><li>语义化优势： <ul><li>增强文档可读性：无样式时仍保持清晰结构</li><li>提升SEO效果：帮助爬虫理解内容权重和上下文关系</li><li>改善可访问性：屏幕阅读器等辅助设备能更准确解析内容</li><li>便于团队协作：符合W3C标准，降低代码维护成本</li></ul></li></ul><h3 id="_2-多媒体支持" tabindex="-1">2. 多媒体支持 <a class="header-anchor" href="#_2-多媒体支持" aria-label="Permalink to &quot;2. 多媒体支持&quot;">​</a></h3><ul><li>原生集成audio和video标签，无需依赖第三方插件即可实现音视频播放</li></ul><h3 id="_3-表单增强" tabindex="-1">3. 表单增强 <a class="header-anchor" href="#_3-表单增强" aria-label="Permalink to &quot;3. 表单增强&quot;">​</a></h3><ul><li>新增输入类型：date/color/email/url/search/tel等</li><li>验证属性：required/pattern/min/max等</li><li>新增元素：datalist/output/progress/meter</li></ul><h3 id="_4-存储方案" tabindex="-1">4. 存储方案 <a class="header-anchor" href="#_4-存储方案" aria-label="Permalink to &quot;4. 存储方案&quot;">​</a></h3><ul><li>localStorage：持久化存储（5MB）</li><li>sessionStorage：会话级存储</li><li>IndexedDB：结构化数据存储</li><li>Application Cache（已弃用，推荐Service Worker）</li></ul><h2 id="三、核心面试题" tabindex="-1">三、核心面试题 <a class="header-anchor" href="#三、核心面试题" aria-label="Permalink to &quot;三、核心面试题&quot;">​</a></h2><h3 id="_1-html5新特性有哪些" tabindex="-1">1. HTML5新特性有哪些？ <a class="header-anchor" href="#_1-html5新特性有哪些" aria-label="Permalink to &quot;1. HTML5新特性有哪些？&quot;">​</a></h3><ul><li>语义化标签体系</li><li>多媒体原生支持</li><li>Canvas/SVG图形绘制</li><li>地理定位API</li><li>Web Workers多线程</li><li>WebSocket全双工通信</li><li>拖放(Drag and Drop) API</li><li>History API（前端路由基础）</li></ul><h3 id="_2-doctype声明的作用" tabindex="-1">2. DOCTYPE声明的作用？ <a class="header-anchor" href="#_2-doctype声明的作用" aria-label="Permalink to &quot;2. DOCTYPE声明的作用？&quot;">​</a></h3><ul><li>声明文档类型</li><li>触发标准模式（Standards Mode）</li><li>避免浏览器进入怪异模式（Quirks Mode）</li></ul><h3 id="_3-语义化标签的优势" tabindex="-1">3. 语义化标签的优势？ <a class="header-anchor" href="#_3-语义化标签的优势" aria-label="Permalink to &quot;3. 语义化标签的优势？&quot;">​</a></h3><ul><li>提升代码可维护性</li><li>增强SEO友好性</li><li>改善可访问性</li><li>便于设备适配（响应式设计）</li></ul><h3 id="_4-web-workers的作用" tabindex="-1">4. Web Workers的作用？ <a class="header-anchor" href="#_4-web-workers的作用" aria-label="Permalink to &quot;4. Web Workers的作用？&quot;">​</a></h3><ul><li>创建后台线程</li><li>避免JS主线程阻塞</li><li>适合复杂计算场景</li><li>通过postMessage通信</li></ul><h2 id="四、进阶面试题" tabindex="-1">四、进阶面试题 <a class="header-anchor" href="#四、进阶面试题" aria-label="Permalink to &quot;四、进阶面试题&quot;">​</a></h2><h3 id="_1-如何实现html5离线应用" tabindex="-1">1. 如何实现HTML5离线应用？ <a class="header-anchor" href="#_1-如何实现html5离线应用" aria-label="Permalink to &quot;1. 如何实现HTML5离线应用？&quot;">​</a></h3><ul><li>使用manifest文件声明缓存资源</li><li>通过Application Cache API管理</li><li>配合Service Worker实现动态缓存</li></ul><h3 id="_2-如何优化html可访问性" tabindex="-1">2. 如何优化HTML可访问性？ <a class="header-anchor" href="#_2-如何优化html可访问性" aria-label="Permalink to &quot;2. 如何优化HTML可访问性？&quot;">​</a></h3><ul><li>使用ARIA角色属性</li><li>保证语义化标签结构</li><li>添加alt文本描述</li><li>键盘导航支持</li><li>颜色对比度达标</li></ul><h3 id="_3-html5地理定位实现原理" tabindex="-1">3. HTML5地理定位实现原理？ <a class="header-anchor" href="#_3-html5地理定位实现原理" aria-label="Permalink to &quot;3. HTML5地理定位实现原理？&quot;">​</a></h3><ul><li>通过Geolocation API获取</li><li>数据源包括GPS/WiFi/IP定位</li><li>需要用户授权</li><li>精度分级处理</li></ul><h3 id="_4-实现拖放功能的步骤" tabindex="-1">4. 实现拖放功能的步骤？ <a class="header-anchor" href="#_4-实现拖放功能的步骤" aria-label="Permalink to &quot;4. 实现拖放功能的步骤？&quot;">​</a></h3><ol><li>设置元素draggable属性</li><li>监听dragstart/dragover/drop事件</li><li>使用dataTransfer对象传输数据</li><li>阻止默认事件行为</li></ol><h3 id="_5-html与xhtml的区别" tabindex="-1">5. HTML与XHTML的区别？ <a class="header-anchor" href="#_5-html与xhtml的区别" aria-label="Permalink to &quot;5. HTML与XHTML的区别？&quot;">​</a></h3><ul><li>语法严格性：XHTML要求标签闭合、属性引号</li><li>MIME类型：XHTML需用application/xhtml+xml</li><li>错误处理：XHTML遇到错误会停止解析</li><li>兼容性：HTML5兼容传统写法</li></ul><p></p><p></p>',34)]))}const b=a(t,[["render",o]]);export{m as __pageData,b as default};
